import {escapeHtml as esc} from '../shared/utils.js?v=0.21.0';
import {POLICIES,hour} from './engine.js?v=0.21.0';
import {diagnose,promiseLabel,informationName,preparationRule,matchedComparison} from './study.js?v=0.21.0';

const dec=n=>Number(n.toFixed(2));
const money=n=>`${n<0?'−':''}£${Math.abs(n).toLocaleString('en-GB',{maximumFractionDigits:0})}`;
export function renderInformation(view){
  const next=view.announcedPrices[0];
  return `<div class="information-bar"><label for="price-notice">Information available <select id="price-notice" ${view.slot?'disabled':''}><option value="0" ${!view.conditions.priceNotice?'selected':''}>Current price only</option><option value="1" ${view.conditions.priceNotice?'selected':''}>Know the next hour’s price</option></select></label><p>${next?`<strong>${hour(next.slot)} announced: ${money(next.price)}/MWh.</strong> Perfect one-hour notice is a hypothetical condition; future offers still arrive in their own hour.`:view.conditions.priceNotice?'No later hour remains. This run used perfect one-hour price notice.':view.done?'This run revealed each price in its own hour.':view.slot?'Prices arrive in their own hour. The information condition stays fixed for this run.':'Prices arrive in their own hour. Choose the information condition before settling the first hour.'}</p></div>`;
}
export function renderInspector(view,selected,probe,open=false){
  return `<details class="option-inspector" id="option-inspector" ${open?'open':''}><summary>Explore a blocked option</summary><p class="hint">Try an action outside the real dispatch slider, or inspect a new offer. Lift promises hypothetically to discover what is holding it back.</p><label class="study-label" for="probe-kind">Option to investigate</label><select id="probe-kind"><option value="dispatch" ${probe.kind==='dispatch'?'selected':''}>Choose a battery output</option>${view.currentOffers.map(c=>`<option value="${esc(c.id)}" ${probe.offerId===c.id&&probe.kind==='offer'?'selected':''}>${c.title} · ${c.mw} MW at ${hour(c.slot)}</option>`).join('')}</select><div id="probe-controls">${renderProbeControls(probe)}</div><div id="probe-results">${renderProbeResults(view,selected,probe)}</div><p class="study-footnote">This holds today’s actual stock and time fixed. It does not cancel a real promise, refund revenue, or undo energy already used. Replaying the day is needed to change earlier actions.</p></details>`;
}
export function renderProbeControls(probe){
  return probe.kind==='dispatch'?`<label class="study-label" for="probe-output">Requested output <output id="probe-output-value">${outputName(probe.dispatchMW)}</output></label><input id="probe-output" type="range" min="-4" max="4" step="0.1" value="${probe.dispatchMW}" aria-valuetext="${outputName(probe.dispatchMW)}"><div class="range-labels"><span>Charge 4 MW</span><span>Export 4 MW</span></div>`:'';
}
export function outputName(value){return value<0?`Charge ${dec(-value)} MW`:value>0?`Export ${dec(value)} MW`:'Hold · 0 MW';}
function rangeRow(label,r,probe){
  const left=Math.max(0,Math.min(100,(r.min+4)/8*100));
  const right=Math.max(0,Math.min(100,(r.max+4)/8*100));
  return `<div class="probe-range"><div><span>${label}</span><strong>${r.feasible?`${dec(r.min)} to ${dec(r.max)} MW`:'No feasible dispatch'}</strong></div><div class="range-track" aria-hidden="true">${r.feasible?`<span class="range-band" style="left:${left}%;width:${right-left}%"></span>`:''}<i class="range-zero"></i>${probe.kind==='dispatch'?`<i class="range-request" style="left:${(probe.dispatchMW+4)/8*100}%"></i>`:''}</div></div>`;
}
export function renderProbeResults(view,selected,probe){
  const d=diagnose(view,selected,probe);
  return `<div class="probe-verdict ${d.allowed?'possible':'blocked'}" role="status"><strong>${d.allowed?'This option is feasible.':d.physical?'Promises close this option.':'Lifting other promises cannot open this option.'}</strong>${d.reasons.length?`<ul>${d.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`:`<p>${probe.kind==='offer'?'There is a physical path to honour this offer alongside the remaining promises.':'This output leaves a physical path to honour the remaining promises.'}</p>`}</div>${rangeRow(probe.kind==='offer'?'With this offer + all promises':'With all promises',d.actualRange,probe)}${d.liftedIds.length?rangeRow('After hypothetical releases',d.range,probe):''}<p class="study-footnote">Negative output imports; positive output exports.${probe.kind==='dispatch'?' The vertical marker is your requested output.':''}</p>${d.removable.length?`<fieldset class="promise-switches"><legend>Hypothetically lift a promise</legend>${d.removable.map(c=>`<label><input type="checkbox" data-lift="${esc(c.id)}" ${d.liftedIds.includes(c.id)?'checked':''}><span>${esc(promiseLabel(view,c))}</span></label>`).join('')}</fieldset>`:''}${d.releaseSets.length?`<div class="release-sets"><p>${d.releaseSets.length===1?'Smallest set that would open this option:':'Alternative smallest sets that would open this option:'}</p>${d.releaseSets.map((set,i)=>`<div><span>${set.map(id=>esc(promiseLabel(view,d.removable.find(c=>c.id===id)))).join('<br>and ')}</span><button class="button small" data-release="${i}">Lift ${set.length===1?'this promise':'this set'}</button></div>`).join('')}</div>`:''}`;
}
export function renderMatched(seed){
  const rows=matchedComparison(seed);
  return `<section class="matched-study"><h3>Promises × information</h3><p>Four runs of this exact day. Battery, prices, offers, settlement and current-price thresholds stay fixed. Change only offer acceptance and the declared price notice.</p><p class="table-pan-hint">Scroll sideways for all results and replay buttons; policy names stay in view.</p><div class="compare-table-wrap" tabindex="0" aria-label="Four matched policy runs"><table class="compare-table"><thead><tr><th scope="col">Policy / information</th><th scope="col">Cash</th><th scope="col">End MWh</th><th scope="col">Net value</th><th scope="col">Replay</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${POLICIES[r.policy].name}<small>${informationName(r.priceNotice)}</small></th><td>${money(r.result.cash)}</td><td>${dec(r.result.energyMWh)}</td><td>${money(r.result.value)}</td><td><button class="button small" data-policy="${r.policy}" data-notice="${r.priceNotice}" aria-label="Replay ${POLICIES[r.policy].name}, ${informationName(r.priceNotice)}">Watch</button></td></tr>`).join('')}</tbody></table></div><p class="hint">${preparationRule} Better information need not improve a simple policy. Compare another day before drawing a conclusion.</p></section>`;
}
